import numpy as np
def read_xyz(path):
    lines = open(path).read().splitlines()
    n = int(lines[0]); atoms=[]; coords=[]
    for ln in lines[2:2+n]:
        p=ln.split(); atoms.append(p[0]); coords.append([float(x) for x in p[1:4]])
    return atoms, np.array(coords)
atoms, xyz = read_xyz('opt2.xyz')
rc = {'C':0.77,'H':0.37,'O':0.66,'N':0.71,'S':1.04,'Rh':1.35}
n=len(atoms)
# build graph
adj={i:set() for i in range(n)}
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(xyz[i]-xyz[j])
        if d < (rc[atoms[i]]+rc[atoms[j]])*1.22 and d>0.3:
            adj[i].add(j); adj[j].add(i)

def rotate_group(xyz, pivot_a, pivot_b, group, angle_deg):
    a=xyz[pivot_a]; b=xyz[pivot_b]; ax=b-a; ax=ax/np.linalg.norm(ax)
    th=np.radians(angle_deg)
    K=np.array([[0,-ax[2],ax[1]],[ax[2],0,-ax[0]],[-ax[1],ax[0],0]])
    R=np.eye(3)+np.sin(th)*K+(1-np.cos(th))*(K@K)
    out=xyz.copy()
    for g in group:
        out[g]=a+(xyz[g]-a)@R.T
    return out

def side_atoms(adj, cut_a, cut_b, from_b):
    """atoms on cut_b's side after removing edge cut_a-cut_b"""
    adj2={k:set(v) for k,v in adj.items()}
    adj2[cut_a].discard(cut_b); adj2[cut_b].discard(cut_a)
    seen=set([from_b]); stack=[from_b]
    while stack:
        u=stack.pop()
        for w in adj2[u]:
            if w not in seen: seen.add(w); stack.append(w)
    return seen

# Tosyl rotation around N(54)-S(51): rotate S-side
grp_S = side_atoms(adj, 54, 51, 51)
print('S-side group size:', len(grp_S))
# Phenethyl rotation around C2(55)-C3(56): rotate C3-side
grp_C = side_atoms(adj, 55, 56, 56)
print('C3-side group size:', len(grp_C))

xyz_new = xyz.copy()
xyz_new = rotate_group(xyz_new, 54, 51, grp_S, 150)   # swing tolyl down
xyz_new = rotate_group(xyz_new, 55, 56, grp_C, 150)   # swing phenyl to left

with open('rotamer.xyz','w') as f:
    f.write(f'{n}\nrotamer adjusted\n')
    for a,c in zip(atoms, xyz_new):
        f.write(f'{a:2s} {c[0]:12.6f} {c[1]:12.6f} {c[2]:12.6f}\n')
print('written rotamer.xyz')

# quick clash check (heavy atoms)
heavy=[i for i,a in enumerate(atoms) if a!='H']
bad=0
for x in range(len(heavy)):
    for y in range(x+1,len(heavy)):
        i,j=heavy[x],heavy[y]
        d=np.linalg.norm(xyz_new[i]-xyz_new[j])
        if d<1.7 and j not in adj[i]:
            bad+=1
            if bad<8: print('close:', atoms[i],i,atoms[j],j,round(d,2))
print('num close non-bonded heavy pairs:', bad)
