    adj={i:set() for i in range(n)}
    for i in range(n):
        for j in range(i+1,n):
            d=np.linalg.norm(xyz[i]-xyz[j])
            if d < (rc[atoms[i]]+rc[atoms[j]])*1.22 and d>0.3:
                adj[i].add(j); adj[j].add(i)
    # close non-bonded heavy-heavy
    heavy=[i for i,a in enumerate(atoms) if a!='H']
    print(f'--- {name} ---')
    cnt=0
    for x in range(len(heavy)):
        for y in range(x+1,len(heavy)):
            i,j=heavy[x],heavy[y]
            if j in adj[i]: continue
            d=np.linalg.norm(xyz[i]-xyz[j])
            if d<2.6:
                cnt+=1
